CREATE TABLE IF NOT EXISTS pais(id INTEGER PRIMARY KEY,nome TEXT NOT NULL,continente TEXT NOT NULL,sigla TEXT NOT NULL UNIQUE,situacao TEXT NOT NULL DEFAULT 'Ativo',versao INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS estado(id INTEGER PRIMARY KEY,pais_id INTEGER NOT NULL REFERENCES pais(id),nome TEXT NOT NULL,regiao TEXT NOT NULL,sigla TEXT NOT NULL,situacao TEXT NOT NULL DEFAULT 'Ativo',versao INTEGER NOT NULL DEFAULT 1,UNIQUE(pais_id,sigla));
CREATE TABLE IF NOT EXISTS cidade(id INTEGER PRIMARY KEY,estado_id INTEGER NOT NULL REFERENCES estado(id),nome TEXT NOT NULL,sigla TEXT NOT NULL,situacao TEXT NOT NULL DEFAULT 'Ativo',versao INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS empresa(id INTEGER PRIMARY KEY,nome TEXT NOT NULL,cnpj TEXT NOT NULL UNIQUE,situacao TEXT NOT NULL DEFAULT 'Ativa',versao INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS aeroporto(id INTEGER PRIMARY KEY,cidade_id INTEGER NOT NULL REFERENCES cidade(id),nome TEXT NOT NULL,sigla TEXT NOT NULL UNIQUE CHECK(length(sigla)=3),situacao TEXT NOT NULL DEFAULT 'Cadastrado',versao INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS aeronave(id INTEGER PRIMARY KEY,empresa_id INTEGER NOT NULL REFERENCES empresa(id),codigo_aeronave TEXT NOT NULL UNIQUE,modelo TEXT NOT NULL,capacidade INTEGER NOT NULL CHECK(capacidade>0),situacao TEXT NOT NULL DEFAULT 'Cadastrada',versao INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS voo(id INTEGER PRIMARY KEY,codigo_voo TEXT NOT NULL UNIQUE,empresa_id INTEGER NOT NULL REFERENCES empresa(id),aeronave_id INTEGER NOT NULL REFERENCES aeronave(id),origem_id INTEGER NOT NULL REFERENCES aeroporto(id),destino_id INTEGER NOT NULL REFERENCES aeroporto(id),partida TEXT NOT NULL,chegada TEXT NOT NULL,situacao TEXT NOT NULL DEFAULT 'Agendado',valor_centavos INTEGER NOT NULL DEFAULT 0 CHECK(valor_centavos>=0),confirmado INTEGER NOT NULL DEFAULT 0 CHECK(confirmado IN(0,1)),versao INTEGER NOT NULL DEFAULT 1,CHECK(origem_id<>destino_id),CHECK(chegada>partida));
CREATE TABLE IF NOT EXISTS escala(id INTEGER PRIMARY KEY,voo_id INTEGER REFERENCES voo(id),sequencial INTEGER NOT NULL CHECK(sequencial>0),origem_id INTEGER NOT NULL REFERENCES aeroporto(id),destino_id INTEGER NOT NULL REFERENCES aeroporto(id),tempo_escala INTEGER NOT NULL CHECK(tempo_escala>0),valor_centavos INTEGER NOT NULL CHECK(valor_centavos>=0),situacao TEXT NOT NULL DEFAULT 'Planejada',versao INTEGER NOT NULL DEFAULT 1,CHECK(origem_id<>destino_id),UNIQUE(voo_id,sequencial));
CREATE TABLE IF NOT EXISTS passageiro(id INTEGER PRIMARY KEY,documento TEXT NOT NULL UNIQUE,nome TEXT NOT NULL,milhagem INTEGER NOT NULL DEFAULT 0 CHECK(milhagem>=0),telefone TEXT NOT NULL DEFAULT '',passaporte TEXT NOT NULL DEFAULT '',situacao TEXT NOT NULL DEFAULT 'Cadastrado',versao INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS bilhete(id INTEGER PRIMARY KEY,codigo_bilhete TEXT NOT NULL UNIQUE,passageiro_id INTEGER NOT NULL REFERENCES passageiro(id),voo_id INTEGER NOT NULL REFERENCES voo(id),origem_id INTEGER NOT NULL REFERENCES aeroporto(id),destino_id INTEGER NOT NULL REFERENCES aeroporto(id),assento INTEGER NOT NULL CHECK(assento>0),hora_prev_partida TEXT NOT NULL,hora_prev_chegada TEXT NOT NULL,portao_embarque TEXT NOT NULL DEFAULT '',classe TEXT NOT NULL DEFAULT 'Econômica',emitido_em TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ','now')),checkin_em TEXT,embarque_em TEXT,cancelado_em TEXT,motivo TEXT NOT NULL DEFAULT '',situacao TEXT NOT NULL DEFAULT 'Emitido',versao INTEGER NOT NULL DEFAULT 1);
CREATE UNIQUE INDEX IF NOT EXISTS bilhete_assento_ativo ON bilhete(voo_id,assento) WHERE situacao<>'Cancelado';
CREATE INDEX IF NOT EXISTS voo_partida ON voo(partida,situacao);
CREATE INDEX IF NOT EXISTS bilhete_passageiro ON bilhete(passageiro_id);
CREATE TABLE IF NOT EXISTS usuario(id INTEGER PRIMARY KEY,email TEXT NOT NULL UNIQUE,nome TEXT NOT NULL,senha_hash TEXT NOT NULL,papel TEXT NOT NULL CHECK(papel IN('gerente','atendente','passageiro')),empresa_id INTEGER REFERENCES empresa(id),passageiro_id INTEGER REFERENCES passageiro(id));
CREATE TABLE IF NOT EXISTS sessao(token_hash TEXT PRIMARY KEY,usuario_id INTEGER NOT NULL REFERENCES usuario(id),expira_em TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS auditoria(id INTEGER PRIMARY KEY,usuario_id INTEGER REFERENCES usuario(id),entidade TEXT NOT NULL,registro_id INTEGER NOT NULL,acao TEXT NOT NULL,motivo TEXT NOT NULL DEFAULT '',criado_em TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ','now')));
CREATE TABLE IF NOT EXISTS manutencao(id INTEGER PRIMARY KEY,entidade TEXT NOT NULL,registro_id INTEGER NOT NULL,motivo TEXT NOT NULL,inicio TEXT NOT NULL,fim TEXT);
